    if (ts.isAsExpression(n) && !(ts.isTypeReferenceNode(n.type) && n.type.getText() === 'const')) {
      const inner = n.expression
      const isInnerUnknown = ts.isAsExpression(inner) && n.type.kind !== ts.SyntaxKind.UnknownKeyword && inner.type.kind === ts.SyntaxKind.UnknownKeyword
      const isPartOfOuter = n.type.kind === ts.SyntaxKind.UnknownKeyword && ts.isAsExpression(n.parent)
